<script setup lang="ts">
import { ref,onMounted } from 'vue'
import { loadPasswordPolicy,passwordError } from './passwordPolicy'
import { request } from '../api'
import UiState from '../ui/UiState.vue'
const data=ref<any>(null),error=ref(''),current=ref(''),next=ref(''),message=ref('')
async function load(){try{data.value=await request('/admin/system')}catch(e){error.value=String(e)}}
async function change(){if(passwordError(next.value)){error.value=passwordError(next.value);return}try{await request('/auth/password',{method:'POST',body:JSON.stringify({current_password:current.value,new_password:next.value})});current.value='';next.value='';message.value='密码已修改，所有会话已撤销，请重新登录。';window.location.assign('/login')}catch(e){error.value=String(e)}}
onMounted(()=>{void load();void loadPasswordPolicy().catch(()=>{})})
</script>
<template><main class="container"><h1>系统状态</h1><UiState v-if="error" class="error" kind="error">{{error}}</UiState><UiState v-else-if="!data" kind="loading">正在读取系统状态…</UiState><section v-if="data" class="card"><dl><dt>应用版本</dt><dd>{{data.release_version||data.application_version}}</dd><dt>构建标识（备份兼容性校验）</dt><dd>{{data.application_version}}</dd><dt>PostgreSQL / API</dt><dd>{{data.postgresql}} / {{data.api}}</dd><dt>数据库迁移版本</dt><dd>{{data.schema}}</dd><dt>媒体目录</dt><dd>{{data.media_writable===null?'一致性备份进行中，写入检查暂缓':data.media_writable?'可写':'不可写'}}</dd><dt>维护服务</dt><dd>{{data.maintenance.online?'在线':'离线'}}</dd><dt>SSD 备份目录</dt><dd>{{data.maintenance.configured?'已就绪':'不可用，请检查维护容器目录与权限'}}</dd><dt>最近一次实际恢复验证</dt><dd>{{data.latest_restore_validation?.restored_at||'未执行'}} {{data.latest_restore_validation?.id||''}}</dd><dt>最近备份任务</dt><dd>{{data.latest_backup_task?.state||'尚未执行'}} {{data.latest_backup_task?.error||''}}</dd><dt>最近备份</dt><dd>{{data.latest_backup?.id||'暂无'}} · 文件校验 {{data.latest_backup?.verified_at||'未执行'}} · 恢复演练 {{data.latest_backup?.restored_at||'未执行'}}</dd></dl><RouterLink to="/admin/maintenance">检查备份任务和失败结果</RouterLink></section><section class="card"><h2>修改自己的密码</h2><p>至少8个字符，不强制字符组合；拒绝常见弱密码。修改后所有设备需重新登录。</p><p role="status">{{message}}</p><form @submit.prevent="change"><label>当前密码<input v-model="current" type="password" required autocomplete="current-password" maxlength="2048" /></label><label>新密码<input v-model="next" type="password" required autocomplete="new-password" maxlength="2048" /></label><button>修改密码并退出全部会话</button></form></section></main></template>
